import{_ as s,C as r,o as d,c as l,j as t,a,E as n,ag as i}from"./chunks/framework.HG0H2VLS.js";const f=JSON.parse('{"title":"SalesLeaderboard","description":"","frontmatter":{},"headers":[],"relativePath":"cc-templates/sales-leaderboard.md","filePath":"cc-templates/sales-leaderboard.md"}'),c={name:"cc-templates/sales-leaderboard.md"};function h(u,e,m,p,b,g){const o=r("ComponentDemo");return d(),l("div",null,[e[0]||(e[0]=t("hr",null,null,-1)),e[1]||(e[1]=t("h2",{id:"title-salesleaderboard",tabindex:"-1"},[a("title: SalesLeaderboard "),t("a",{class:"header-anchor",href:"#title-salesleaderboard","aria-label":'Permalink to "title: SalesLeaderboard"'},"​")],-1)),e[2]||(e[2]=t("h1",{id:"salesleaderboard",tabindex:"-1"},[a("SalesLeaderboard "),t("a",{class:"header-anchor",href:"#salesleaderboard","aria-label":'Permalink to "SalesLeaderboard"'},"​")],-1)),e[3]||(e[3]=t("blockquote",null,[t("p",null,[t("code",null,"/control/sales-leaderboard"),a(" on v3, built on the Live Dashboard (links its CSS): toolbar with classic's Time frame + Currency (Select, kept in the URL), StatCard Xl KPIs (Sales in the time frame, Sales this year vs last, Top sales person), Monthly sales hero (this year blue vs last year orange dashed, part month dotted, table view), Top sales teams leaderboard with share bars, Top sales people + Most recent sales tables, 5-minute refresh")])],-1)),n(o,{src:"/demos/src/cc/templates/SalesLeaderboard/SalesLeaderboard.html"}),e[4]||(e[4]=i('<h2 id="classic-→-v3" tabindex="-1">Classic → v3 <a class="header-anchor" href="#classic-→-v3" aria-label="Permalink to &quot;Classic → v3&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Classic</th><th>v3</th></tr></thead><tbody><tr><td>Time Frame select (Current Week, 7 Days, Current Month, Previous Month, 30 Days, Current Year, 12 Months; default Current Week)</td><td><strong>Select</strong> in a toolbar above the KPIs, no visible label (<code>aria-label</code>), the window&#39;s dates beside it, as short as they can be and still exact (&quot;Mon 5 Oct&quot;, &quot;1–30 Sept&quot;, &quot;5 Sept – 5 Oct&quot;, &quot;5 Nov 2025 – 5 Oct&quot;). Re-runs the leaderboards and the two time-frame KPIs, as classic&#39;s change handler re-ran <code>getData(&#39;all&#39;)</code></td></tr><tr><td>Currency select (the zone&#39;s order currencies, store default first) — <strong>reloaded the page</strong></td><td><strong>Select</strong> beside it; re-renders everything in place. Both choices stay in the URL as classic&#39;s <code>?timeframe=</code> / <code>?currency=</code>, so a link opens the same view</td></tr><tr><td>Total Monthly Sales (Chart.js line, this year vs last, Jan–Dec, &quot;Order Value&quot; axis, ex VAT)</td><td><strong>Monthly sales</strong> hero card: this year lagoon + filled, last year purple + dashed (the house pair with Live Dashboard and Contract Analysis, designer 2026-10-07; was blue + orange), delta Badge &quot;+n% year to date&quot;, crosshair tooltip, direct labels, legend, <strong>View as table</strong>. This year stops at the current month, and that month&#39;s segment is <strong>dotted</strong> with a &quot;October to date&quot; legend key: classic drew the months still to come as 0, and a part-month total then reads as a collapse</td></tr><tr><td>Top Sales Teams list (order value + team), view more (5 +5)</td><td>Leaderboard card beside the chart: rank, team link, value right-aligned, <strong>share-of-top bar</strong>; Show more +5</td></tr><tr><td>Top Sales People table (Sales Representative, Sales Team, Business Unit, No. Orders, Total Value), view more (5 +5)</td><td><strong>Top sales people</strong> Datatables + Table, rep with avatar; &quot;Multiple&quot; for a rep in several teams / units, as classic; Show more +5</td></tr><tr><td>Most Recent Sales table (Product, Order No., Product Category, Product Line, Value, Account), view more (5 +5)</td><td><strong>Most recent sales</strong> table with the same columns plus <strong>Ordered</strong> (the date, which classic loaded but never showed); Value moved to the end so values line up with the other table; Show more +5</td></tr><tr><td><code>setTimeout(aosGetData(&#39;all&#39;), 300000)</code>, only while the window has focus</td><td>Same 5-minute refresh while the tab is visible, now with &quot;Updated n m ago&quot; in the toolbar; a line that arrives with a refresh gets one brief highlight</td></tr><tr><td>—</td><td>KPIs <strong>Sales</strong> (time frame; orders, average order), <strong>Sales this year</strong> (vs the same span last year, best month), <strong>Top sales person</strong> (time frame; value, orders) — derived from data classic already loads</td></tr></tbody></table><p>Every leaderboard repeats the time frame beside its title, so a card read alone says what window it covers. Links are classic&#39;s own, in a new tab as classic opens them: sales-team (SalesTeamCode), contacts UserView (UserCode), catalogue-item (CatalogueItemCode). Order numbers stay plain text, as classic.</p><p>Money is formatted as classic&#39;s <code>FormatPriceList</code> does it, from the real Currency rows: GBP <code>£</code> with 2 decimals, EUR <code>€</code> and USD <code>$</code> with none. KPIs and the chart axis round to whole units; the tables keep each currency&#39;s own decimals.</p><h2 id="to-confirm-classic-quirk-changed-in-the-demo" tabindex="-1">To confirm (classic quirk, changed in the demo) <a class="header-anchor" href="#to-confirm-classic-quirk-changed-in-the-demo" aria-label="Permalink to &quot;To confirm (classic quirk, changed in the demo)&quot;">​</a></h2><p><strong>Previous Month had no end date.</strong> <code>getTimeFrame(4)</code> returns the first of last month and every query is <code>Created &gt;= start</code>, so classic&#39;s &quot;Previous Month&quot; counted last month <strong>and everything since</strong>. The demo ends it at the first of this month. If classic&#39;s behaviour is wanted, that is a one-line change in <code>windowRange()</code>.</p><h2 id="data" tabindex="-1">Data <a class="header-anchor" href="#data" aria-label="Permalink to &quot;Data&quot;">​</a></h2><p>Real (AffinoComrz config, 2026-10-05): currencies and their formats; product lines (Affino, Digital Leaders Forum, CEO Forum); product categories (Consultancy, Training, SaaS, Design and Build, Support); business unit &quot;Affino&quot;; sales team &quot;Main Affino Sales Team&quot;. Sales people are the staff names the other CC demos use; accounts are real Affino clients. <strong>affino.com itself has one sales team and one business unit</strong>, so its live leaderboard has a single row; the demo adds six teams and two units to show the screen at the size it is built for. Orders are generated from a fixed seed relative to today (about five a weekday, a quarter of them owner-less web orders that count in the monthly totals but no leaderboard, as classic&#39;s <code>OwnerUserCode &gt; 0</code>), so every time frame has data and the demo is stable. Order rows themselves were not read (customer data).</p><h2 id="layout-values-all-borrowed-no-new-tokens" tabindex="-1">Layout values (all borrowed, no new tokens) <a class="header-anchor" href="#layout-values-all-borrowed-no-new-tokens" aria-label="Permalink to &quot;Layout values (all borrowed, no new tokens)&quot;">​</a></h2><p>Everything in Live Dashboard&#39;s table applies (grid, gaps, card chrome, card title, share bar, canvas). New here:</p><table tabindex="0"><thead><tr><th>Property</th><th>Token</th><th>From</th></tr></thead><tbody><tr><td>Toolbar gap</td><td><code>spacing-4</code> / <code>spacing-5</code></td><td>Live Dashboard&#39;s full-width gap / block gap</td></tr><tr><td>Time frame Select width</td><td>cap <code>size-3</code> (192px), <code>flex: 0 1</code></td><td>— fits &quot;Previous month&quot;; a cap, so it yields on a phone</td></tr><tr><td>Currency Select width</td><td>cap <code>size-1</code> (128px), <code>flex: 0 1</code>; the grid&#39;s second column below 767</td><td>—</td></tr><tr><td>Range / Updated / card meta text</td><td>title, <code>fixed-3xs</code>, medium, <code>leading-sm</code>, <code>text-contrast</code></td><td>Mark, 2026-10-05</td></tr><tr><td>Part-month legend key</td><td>2px <strong>dotted</strong> <code>accent-lagoon-solid</code></td><td>Live Dashboard&#39;s legend keys</td></tr><tr><td>KPI tiles</td><td><code>lagoon</code>, <code>jade</code> (was blue), <code>violet-radix</code></td><td>card accents lead with lagoon, blue only after the other accents (designer, 2026-10-07)</td></tr><tr><td>New-line highlight</td><td>Live Dashboard&#39;s <code>cc-live-changed</code> wash</td><td>—</td></tr><tr><td>Narrowest phones</td><td><code>@container cs-page (max-width: 320px)</code> (≈ a 370px page): Top sales people&#39;s name ends in &quot;…&quot; with the full name in its <code>title</code> (<code>max-inline-size: 0</code> on the name cell takes it out of the min-content sum), and the tables&#39; header labels wrap. Fixes the last overflow (18 / 8px at 340 / 350px pages)</td><td>Mark, 2026-10-07</td></tr><tr><td>Table fit</td><td><code>data-fit=&quot;even&quot;</code> — every column the same width where content allows (Mark, 2026-10-07), as Live Dashboard. <strong>DatatablesFit.js</strong> (<code>src/components/Datatables/</code>) — the listings&#39; fit for dashboard tables: natural widths, spare shared (water-filling; <code>data-snug</code> capped at 224, then spread evenly when all are capped), and when a row does not fit a kebab appears and columns drop in <code>data-drop</code> order into the detail row. Top sales people: keep Sales representative + Total value; drop Business unit → Sales team → Orders. Most recent sales: keep Product + Value; drop Product line → Product category → Order no. → Account → Ordered. Replaces the ≤767 hide-column CSS and the earlier <code>spreadColumns()</code></td><td>the listings&#39; fit (designer 2026-09-18 → 22); Mark, 2026-10-07: &quot;the tables aren&#39;t responsive friendly&quot;</td></tr></tbody></table><h2 id="responsive" tabindex="-1">Responsive <a class="header-anchor" href="#responsive" aria-label="Permalink to &quot;Responsive&quot;">​</a></h2><ul><li>Live Dashboard&#39;s rules apply: KPI tiles stack their breakdown below 384px; below 1023 (<code>cs-page</code>) the chart and the <strong>teams card</strong> each take the full row; below 767 one column.</li><li><strong>Below 767 (<code>cs-page</code>):</strong> Top sales people keeps rep, orders and value (Sales team and Business unit go); Most recent sales keeps product, account and value. Headers and text cells may wrap. Measured at 390: both tables 309 / 309 (the people table was 311 / 309 until headers could wrap); the page 323 / 323.</li><li><strong>Toolbar below 767:</strong> a two-column grid (Mark, 2026-10-05: &quot;sharper&quot; — the wrapped toolbar left ragged widths and three stray lines): the time frame Select fills the row beside the currency&#39;s 128px (<code>size-1</code>), both flush with the cards&#39; edges; the dates and &quot;Updated&quot; share the second line, the dates truncating with an ellipsis if they ever need to. Checked at 390 with the longest labels (Previous month, 12 months).</li></ul><h2 id="full-width" tabindex="-1">Full width <a class="header-anchor" href="#full-width" aria-label="Permalink to &quot;Full width&quot;">​</a></h2><p>Live Dashboard&#39;s treatment, unchanged: 12px page inset and gaps, flat cards.</p><h2 id="accessibility" tabindex="-1">Accessibility <a class="header-anchor" href="#accessibility" aria-label="Permalink to &quot;Accessibility&quot;">​</a></h2><p>Both Selects are named by <code>aria-label</code>; a change is announced (&quot;Showing 30 days&quot;, &quot;Showing EUR sales&quot;) through a visually-hidden polite region, anchored in the toolbar. The canvas is <code>role=&quot;img&quot;</code> with a label that follows the currency; <strong>View as table</strong> gives every month, marking the current one &quot;(to date)&quot;. The part-month segment is dotted, not only lighter, so it does not rest on colour. No highlight animation under reduced motion.</p><h2 id="backend-todo-backend-salesleaderboard" tabindex="-1">Backend (<code>TODO(backend:SalesLeaderboard)</code>) <a class="header-anchor" href="#backend-todo-backend-salesleaderboard" aria-label="Permalink to &quot;Backend (`TODO(backend:SalesLeaderboard)`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>id</th><th>What</th></tr></thead><tbody><tr><td><code>sales-data</code></td><td>Every order is mock. Live = SalesLeaderboard.cfc: getZoneCurrencies, getTotalMonthlySales (this year + last by month, ex VAT), getTopSalesTeams, getTopSalesPeople, getMostRecentSales from the time frame&#39;s start, MaxRows paging (5 +5, capped at 100), excluding the CRM profile&#39;s order / payment statuses</td></tr><tr><td><code>sales-refresh</code></td><td>Call <code>getData&amp;type=all</code> with the time frame, currency and each list&#39;s MaxRows every 5 minutes while visible (classic&#39;s salesleaderboard.js) and re-render. Keep classic&#39;s &quot;Access Denied&quot; redirect (security code 14)</td></tr></tbody></table>',19))])}const v=s(c,[["render",h]]);export{f as __pageData,v as default};
